    "backend": {
      "path": ".",
      "tech_stack": ["python", "httpx", "beautifulsoup4", "pytest"],
      "port": null,
      "dev_command": "python -m awesome_researcher",
      "test_command": "python -m pytest tests/ -x -q"
    }
  },
  "infrastructure": {
    "docker": true,
    "database": null
  },
  "conventions": {
    "linter": "none",
    "formatter": "black-style (dataclasses, __future__ annotations)",
