}

{
  "files_to_modify": {
    "backend": [
      "awesome_researcher/parsers/markdown_parser.py",
      "tests/test_phase3_parsers.py"
    ]
  },
  "files_to_create": [
    "tests/test_phase3_roundtrip_fixtures.py"
  ],
  "files_to_reference": [
    "awesome_researcher/parsers/awesome_parser.py",
    "awesome_researcher/renderers/list_renderer.py",
    "tests/test_phase3_parsers.py",
    "tests/fixtures/awesome-go.README.md",
    "tests/fixtures/awesome-python.README.md",
    "tests/fixtures/awesome-machine-learning.README.md"
  ],
  "patterns": {
    "parser_pattern": "Line-based regex parser in markdown_parser.py; ParsedList/Category/ParsedItem dataclasses with to_dict(); source_text + source_lines retained for byte-preserving patching",
    "fetch_pattern": "awesome_parser.py: httpx.AsyncClient, raw.githubusercontent refs HEAD/main/master then GitHub contents API fallback; emits events via EventBus",
    "renderer_pattern": "list_renderer.SourcePatcher.patch() guarantees zero-insert output == parsed.source_text byte-for-byte; inserts spliced after last_item_line with local bullet prefix",
    "test_pattern": "Offline pytest tests run real parser over real fixture snippets from tests/fixtures/; no network, no mocks"
  },
  "existing_implementations": {
    "description": "Parser, fetcher, and source-preserving patcher already exist. beautifulsoup4 >=4.12 is declared in pyproject.toml/requirements.txt but not used anywhere. Existing tests cover standard items, nested headings, no-desc links, badges/TOC, and two SourcePatcher byte-preservation tests.",
    "relevant_files": [
      "awesome_researcher/parsers/markdown_parser.py",
      "awesome_researcher/parsers/awesome_parser.py",
      "awesome_researcher/renderers/list_renderer.py",
      "tests/test_phase3_parsers.py"
    ]
  },
  "gaps_vs_spec": [
    "beautifulsoup4 not integrated: inline HTML links (e.g. <a href=...> in prose/HTML fragments) and HTML-comment-wrapped content are dropped entirely rather than parsed",
    "Round-trip byte-for-byte guarantee not verified against the three real fixture READMEs (only small snippets)",
    "Non-link content handling (prose, sub-lists under items, HTML blocks) lacks explicit test coverage"
  ]
}

{
